const output = $json.text || $json.output || $json.response;

let data;

try {

    data = JSON.parse(output);

} catch (error) {

    // Try to extract JSON if the model added extra text

    const match =
        output.match(/\{[\s\S]*\}/);

    if (!match) {

        throw new Error(
            "LLM did not return valid JSON"
        );

    }

    data = JSON.parse(match[0]);

}


return [

    {
        json: {

            searchQuery: data.searchQuery,

            count: Math.min(
                Math.max(
                    Number(data.count) || 5,
                    1
                ),
                10
            ),

            preference:
                data.preference === "distance"
                ? "distance"
                : "best"

        }
    }

];

const places = $json.places || [];

const results = places.map(place => {

    const location = place.location || {};

    return {

        name:
            place.displayName?.text
            || "Unknown place",

        address:
            place.formattedAddress
            || "Address unavailable",

        rating:
            place.rating
            || null,

        reviews:
            place.userRatingCount
            || 0,

        phone:
            place.nationalPhoneNumber
            || null,

        lat:
            location.latitude
            || null,

        lng:
            location.longitude
            || null,

        mapsUrl:
            place.googleMapsUri
            || null

    };

});


return [

    {

        json: {

            results: results

        }

    }

];
